            _log(endpoint, client_id, None, "UNAUTHORIZED", started, error_code="CLIENT_QUOTA_INVALID")
            return _err("UNAUTHORIZED", "Client is not permitted (invalid quota configuration).")
        if not isinstance(quota_per_day, int) or not (1 <= quota_per_day <= 1000000):
            _log(endpoint, client_id, None, "UNAUTHORIZED", started, error_code="CLIENT_QUOTA_INVALID")
            return _err("UNAUTHORIZED", "Client is not permitted (invalid quota configuration).")

        if _count(minute_start) >= quota_per_minute:
            _log(endpoint, client_id, None, "RATE_LIMIT", started, error_code="QUOTA_PER_MINUTE")
            return _err("RATE_LIMIT", "Rate limit exceeded for this client (per-minute quota).")
        if _count(day_start) >= quota_per_day:
            _log(endpoint, client_id, None, "QUOTA_EXCEEDED", started, error_code="QUOTA_PER_DAY")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this client.")
        return None

    started = time.time()
    endpoint = "get_precise_results"

    if not isinstance(keyword, str):
        _log(endpoint, None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "keyword must be a string")
    if len(keyword.strip()) < 1 or len(keyword) > 200:
        _log(endpoint, None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "keyword must be non-empty and at most 200 characters")

    if search_type is None:
        search_type = "user"
    if not isinstance(search_type, str) or search_type not in ("user", "video", "live", "article"):
        _log(endpoint, None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "search_type must be one of: user, video, live, article")

    client = _resolve_ambient_client()
    if not client:
        _log(endpoint, None, None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "Missing/invalid/disabled API client.")
    client_id = client["id"]

    lim_err = _enforce_limits(client_id, client.get("quota_per_minute"), client.get("quota_per_day"), endpoint, started)
    if lim_err:
        return lim_err

    tool_name = "get_precise_results"
    page = 1
    cache_key = _cache_key(tool_name, keyword, search_type, page)

    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        queries = []
    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []

    now = _now_utc()
    today = now.date()

    cached_q = None
    for q in queries:
        if not isinstance(q, dict):
            continue
        if q.get("client_id") != client_id:
            continue
        if q.get("upstream_cache_key") != cache_key:
            continue
        if q.get("status") != "succeeded":
            continue
        created = _parse_iso(q.get("created_at"))
        if not created or created.date() != today:
            continue
        exp = _parse_iso(q.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        cached_q = q
        break

    qid = _gen_id("bili_qry")
    qrow = {
        "id": qid,
        "client_id": client_id,
        "tool_name": tool_name,
        "keyword": keyword,
        "search_type": search_type,
        "page": 1,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "upstream_cache_key": cache_key,
        "cache_hit": bool(cached_q),
        "expires_at": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    queries.append(qrow)
    _save("search_queries.json", queries)

    # Use cached succeeded results if available; filter exact matches + type
    if cached_q:
        qrow["status"] = "running"
        qrow["started_at"] = _now_iso()
        qrow["updated_at"] = _now_iso()
        _save("search_queries.json", queries)

        cached_items = [r for r in results if isinstance(r, dict) and r.get("query_id") == cached_q.get("id")]
        filtered = []
        for r in cached_items:
            if r.get("result_type") != search_type:
                continue
            if r.get("exact_match") is True:
                filtered.append(r)
            else:
                # If store has older rows without exact_match computed, compute stably but do not mutate (read path)
                title = r.get("title")
                if isinstance(title, str) and _stable_exact_match(keyword, title):
                    filtered.append(r)

        qrow["status"] = "succeeded"
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = _now_iso()
        _save("search_queries.json", queries)

        clients = _load("api_clients.json")
        if isinstance(clients, list):
            for c in clients:
                if isinstance(c, dict) and c.get("id") == client_id:
                    c["last_used_at"] = _now_iso()
                    c["updated_at"] = _now_iso()
                    break
            _save("api_clients.json", clients)

        _log(endpoint, client_id, None, "ok", started)
        return {
            "query": qrow,
            "cache_reused_from_query_id": cached_q.get("id"),
            "search_type": search_type,
            "keyword": keyword,
            "results": filtered,
            "meta": {"total": len(filtered)},
        }

    # Offline: record failed query but return empty precise results (not an API error)
    qrow["status"] = "running"
    qrow["started_at"] = _now_iso()
    qrow["updated_at"] = _now_iso()
    _save("search_queries.json", queries)

    qrow["status"] = "failed"
    qrow["error_code"] = "UPSTREAM_UNAVAILABLE_OFFLINE"
    qrow["error_message"] = "Upstream is unavailable in offline mode; returning empty precise result set."
    qrow["finished_at"] = _now_iso()
    qrow["updated_at"] = _now_iso()
    _save("search_queries.json", queries)

    _log(endpoint, client_id, None, "ok", started, error_code="UPSTREAM_UNAVAILABLE_OFFLINE")
    return {
        "query": qrow,
        "search_type": search_type,
        "keyword": keyword,
        "results": [],
        "meta": {"total": 0},
    }

def get_video_danmaku(bv_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0168000" if __import__("os").path.isdir("./environment_mix/0168000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, client_id, credential, status_code, started, error_code=None):
        fn = _ensure_request_logs()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        finished = time.time()
        logs.append(
            {
                "id": f"req_{int(finished*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "client_id": client_id,
                "credential": credential,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int(max(0, (finished - started) * 1000)),
                "created_at": _now_iso(),
            }
        )
        _save(fn, logs)

    def _gen_id(prefix):
        t = int(time.time() * 1000)
        return f"{prefix}_01{t:013x}{os.getpid():04x}{int(t%1000):03x}"

    def _resolve_ambient_client():
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
        if not active:
            return None
        def _lu(c):
            dt = _parse_iso(c.get("last_used_at"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        active.sort(key=_lu)
        return active[0]

    def _enforce_limits(client_id, quota_per_minute, quota_per_day, endpoint, started):
        fn = _ensure_request_logs()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        minute_start = now.replace(second=0, microsecond=0)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

        def _count(since_dt):
            n = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != client_id:
                    continue
                ts = _parse_iso(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= since_dt:
                    n += 1
            return n

        if not isinstance(quota_per_minute, int) or not (1 <= quota_per_minute <= 6000):
            _log(endpoint, client_id, None, "UNAUTHORIZED", started, error_code="CLIENT_QUOTA_INVALID")
            return _err("UNAUTHORIZED", "Client is not permitted (invalid quota configuration).")
        if not isinstance(quota_per_day, int) or not (1 <= quota_per_day <= 1000000):
            _log(endpoint, client_id, None, "UNAUTHORIZED", started, error_code="CLIENT_QUOTA_INVALID")
            return _err("UNAUTHORIZED", "Client is not permitted (invalid quota configuration).")

        if _count(minute_start) >= quota_per_minute:
            _log(endpoint, client_id, None, "RATE_LIMIT", started, error_code="QUOTA_PER_MINUTE")
            return _err("RATE_LIMIT", "Rate limit exceeded for this client (per-minute quota).")
        if _count(day_start) >= quota_per_day:
            _log(endpoint, client_id, None, "QUOTA_EXCEEDED", started, error_code="QUOTA_PER_DAY")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this client.")
        return None

    started = time.time()
    endpoint = "get_video_danmaku"

    if not isinstance(bv_id, str):
        _log(endpoint, None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "bv_id must be a string")
    bv_id = bv_id.strip()
    if not bv_id:
        _log(endpoint, None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "bv_id is required")
    if not re.match(r"^BV[0-9A-Za-z]{10}$", bv_id):
        _log(endpoint, None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "bv_id must match ^BV[0-9A-Za-z]{10}$")

    client = _resolve_ambient_client()
    if not client:
        _log(endpoint, None, None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "Missing/invalid/disabled API client.")
    client_id = client["id"]

    lim_err = _enforce_limits(client_id, client.get("quota_per_minute"), client.get("quota_per_day"), endpoint, started)
    if lim_err:
        return lim_err

    dreqs = _load("danmaku_requests.json")
    if not isinstance(dreqs, list):
        dreqs = []
    dresps = _load("danmaku_responses.json")
    if not isinstance(dresps, list):
        dresps = []

    now = _now_utc()

    # Find latest non-expired response for bv_id, preferring fresh over stale, excluding purged
    def _resp_sort_key(r):
        fetched = _parse_iso(r.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        status = r.get("status")
        # fresh first, then stale
        prio = 0 if status == "fresh" else (1 if status == "stale" else 9)
        return (prio, -int(fetched.timestamp()))

    candidates = []
    for r in dresps:
        if not isinstance(r, dict):
            continue
        if r.get("bv_id") != bv_id:
            continue
        if r.get("status") == "purged":
            continue
        exp = _parse_iso(r.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        candidates.append(r)
    candidates.sort(key=_resp_sort_key)
    cached_resp = candidates[0] if candidates else None

    # Always create a danmaku_requests row (business rule)
    req_id = _gen_id("bili_dreq")
    req_row = {
        "id": req_id,
        "client_id": client_id,
        "bv_id": bv_id,
        "status": "queued",
        "cache_hit": bool(cached_resp),
        "response_id": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    dreqs.append(req_row)
    _save("danmaku_requests.json", dreqs)

    if cached_resp:
        req_row["status"] = "running"
        req_row["started_at"] = _now_iso()
        req_row["updated_at"] = _now_iso()
        _save("danmaku_requests.json", dreqs)

        req_row["response_id"] = cached_resp.get("id")
        # Enforce rule: succeeded only if response exists and referenced
        if not isinstance(req_row["response_id"], str) or not any(isinstance(x, dict) and x.get("id") == req_row["response_id"] for x in dresps):
            req_row["status"] = "failed"
            req_row["error_code"] = "CACHE_LINK_INVALID"
            req_row["error_message"] = "Cached response link invalid; returning empty payload."
        else:
            req_row["status"] = "succeeded"
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = _now_iso()
        _save("danmaku_requests.json", dreqs)

        if req_row["status"] == "succeeded":
            clients = _load("api_clients.json")
            if isinstance(clients, list):
                for c in clients:
                    if isinstance(c, dict) and c.get("id") == client_id:
                        c["last_used_at"] = _now_iso()
                        c["updated_at"] = _now_iso()
                        break
                _save("api_clients.json", clients)

        _log(endpoint, client_id, None, "ok", started)
        return {"request": req_row, "response": cached_resp}

    # Offline: create failed request and return empty payload (not a CONFLICT error)
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = _now_iso()
    _save("danmaku_requests.json", dreqs)

    req_row["status"] = "failed"
    req_row["error_code"] = "UPSTREAM_UNAVAILABLE_OFFLINE"
    req_row["error_message"] = "Upstream is unavailable in offline mode; returning no danmaku."
    req_row["finished_at"] = _now_iso()
    req_row["updated_at"] = _now_iso()
    _save("danmaku_requests.json", dreqs)

    _log(endpoint, client_id, None, "ok", started, error_code="UPSTREAM_UNAVAILABLE_OFFLINE")
    return {"request": req_row, "response": None}

def whoami(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0168000" if __import__("os").path.isdir("./environment_mix/0168000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs():
        os.makedirs(_DB, exist_ok=True)
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, client_id, api_key_ref, status, started_ts, extra=None):
        # Best-effort logging; never fail the call due to logging.
        try:
            fn = _ensure_logs()
            logs = _load(fn)
            finished_ts = time.time()
            row = {
                "id": "req_" + str(int(finished_ts * 1000)) + "_" + str(len(logs) + 1),
                "endpoint": endpoint,
                "client_id": client_id,
                "api_key_ref": api_key_ref,
                "status": status,
                "latency_ms": int(max(0, (finished_ts - started_ts) * 1000)),
                "created_at": _now_iso(),
            }
            if isinstance(extra, dict) and extra:
                row["meta"] = extra
            logs.append(row)
            _save(fn, logs)
        except Exception:
            return

    def _auth_and_limits(endpoint, api_key_value, started_ts):
        if api_key_value is None or not isinstance(api_key_value, str) or not api_key_value.strip():
            _log(endpoint, None, None, "UNAUTHORIZED", started_ts, {"reason": "missing_api_key"})
            return None, _err("UNAUTHORIZED", "Missing or invalid API key.")

        api_clients = _load("api_clients.json")
        # IMPORTANT: authenticate by matching plaintext value (client-visible), not by comparing to stored hash.
        # Since store only has api_key_hash, we accept either exact match to that value OR client id.
        client = None
        for r in api_clients:
            if not isinstance(r, dict):
                continue
            if r.get("id") == api_key_value or r.get("api_key_hash") == api_key_value:
                client = r
                break

        if not client:
            _log(endpoint, None, api_key_value, "UNAUTHORIZED", started_ts, {"reason": "invalid_api_key"})
            return None, _err("UNAUTHORIZED", "Invalid API key.")

        if client.get("status") != "active":
            _log(endpoint, client.get("id"), api_key_value, "UNAUTHORIZED", started_ts, {"reason": "client_not_active", "status": client.get("status")})
            return None, _err("UNAUTHORIZED", "API client is not active.", status=client.get("status"))

        # Rate/quota enforcement using request_logs.json (all calls; reads included)
        quota_per_minute = client.get("quota_per_minute")
        quota_per_day = client.get("quota_per_day")
        if not isinstance(quota_per_minute, int) or quota_per_minute < 1 or quota_per_minute > 6000:
            _log(endpoint, client.get("id"), api_key_value, "VALIDATION_ERROR", started_ts, {"reason": "bad_quota_per_minute"})
            return None, _err("VALIDATION_ERROR", "Client quota_per_minute is invalid.")
        if not isinstance(quota_per_day, int) or quota_per_day < 1 or quota_per_day > 1000000:
            _log(endpoint, client.get("id"), api_key_value, "VALIDATION_ERROR", started_ts, {"reason": "bad_quota_per_day"})
            return None, _err("VALIDATION_ERROR", "Client quota_per_day is invalid.")

        logs = _load(_ensure_logs())
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        per_min = 0
        per_day = 0
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client.get("id"):
                continue
            ts = _parse_dt(e.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1

        # This request would be the next one; refuse without creating domain rows.
        if per_min >= quota_per_minute:
            _log(endpoint, client.get("id"), api_key_value, "RATE_LIMIT", started_ts, {"per_minute": per_min, "limit": quota_per_minute})
            return None, _err("RATE_LIMIT", "Rate limit exceeded.", limit=quota_per_minute, window_seconds=60, used=per_min)
        if per_day >= quota_per_day:
            _log(endpoint, client.get("id"), api_key_value, "QUOTA_EXCEEDED", started_ts, {"per_day": per_day, "limit": quota_per_day})
            return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=quota_per_day, window_seconds=86400, used=per_day)

        return {
            "client": client,
            "usage": {"per_minute_used": per_min, "per_day_used": per_day, "quota_per_minute": quota_per_minute, "quota_per_day": quota_per_day},
            "api_clients": api_clients,
        }, None

    started = time.time()

    # Validate inputs first
    if api_key is None or not isinstance(api_key, str):
        _log("whoami", None, None, "VALIDATION_ERROR", started, {"reason": "api_key_type"})
        return _err("VALIDATION_ERROR", "api_key must be a string.")

    ctx, e = _auth_and_limits("whoami", api_key, started)
    if e:
        return e

    client = ctx["client"]
    usage = ctx["usage"]

    # Mutation: update last_used_at on successful request
    try:
        now_iso = _now_iso()
        updated = False
        for r in ctx["api_clients"]:
            if isinstance(r, dict) and r.get("id") == client.get("id"):
                r["last_used_at"] = now_iso
                r["updated_at"] = now_iso
                updated = True
                break
        if updated:
            _save("api_clients.json", ctx["api_clients"])
    except Exception:
        # Don't fail the request due to metadata update.
        pass

    _log("whoami", client.get("id"), api_key, "OK", started)

    return {
        "client": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
            "last_used_at": client.get("last_used_at"),
        },
        "scopes": [],  # schema has no scopes; return empty list
        "rate_limit": usage,
    }

