                "id": "req_" + str(int(finished_ts * 1000)) + "_" + str(len(logs) + 1),
                "endpoint": endpoint,
                "client_id": client_id,
                "api_key_ref": api_key_ref,
                "status": status_code,
                "latency_ms": int(max(0, (finished_ts - started_ts) * 1000)),
                "created_at": _now_iso(),
            }
            if isinstance(extra, dict) and extra:
                row["meta"] = extra
            logs.append(row)
            _save(fn, logs)
        except Exception:
            return

    def _auth_and_limits(endpoint, api_key_value, started_ts):
        if api_key_value is None or not isinstance(api_key_value, str) or not api_key_value.strip():
            _log(endpoint, None, None, "UNAUTHORIZED", started_ts, {"reason": "missing_api_key"})
            return None, _err("UNAUTHORIZED", "Missing or invalid API key.")

        api_clients = _load("api_clients.json")
        client = None
        for r in api_clients:
            if not isinstance(r, dict):
                continue
            if r.get("id") == api_key_value or r.get("api_key_hash") == api_key_value:
                client = r
                break

        if not client:
            _log(endpoint, None, api_key_value, "UNAUTHORIZED", started_ts, {"reason": "invalid_api_key"})
            return None, _err("UNAUTHORIZED", "Invalid API key.")

        if client.get("status") != "active":
            _log(endpoint, client.get("id"), api_key_value, "UNAUTHORIZED", started_ts, {"reason": "client_not_active", "status": client.get("status")})
            return None, _err("UNAUTHORIZED", "API client is not active.", status=client.get("status"))

        qpm = client.get("quota_per_minute")
        qpd = client.get("quota_per_day")
        if not isinstance(qpm, int) or qpm < 1 or qpm > 6000:
            _log(endpoint, client.get("id"), api_key_value, "VALIDATION_ERROR", started_ts, {"reason": "bad_quota_per_minute"})
            return None, _err("VALIDATION_ERROR", "Client quota_per_minute is invalid.")
        if not isinstance(qpd, int) or qpd < 1 or qpd > 1000000:
            _log(endpoint, client.get("id"), api_key_value, "VALIDATION_ERROR", started_ts, {"reason": "bad_quota_per_day"})
            return None, _err("VALIDATION_ERROR", "Client quota_per_day is invalid.")

        logs = _load(_ensure_logs())
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        per_min = 0
        per_day = 0
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client.get("id"):
                continue
            ts = _parse_dt(e.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1

        if per_min >= qpm:
            _log(endpoint, client.get("id"), api_key_value, "RATE_LIMIT", started_ts, {"per_minute": per_min, "limit": qpm})
            return None, _err("RATE_LIMIT", "Rate limit exceeded.", limit=qpm, window_seconds=60, used=per_min)
        if per_day >= qpd:
            _log(endpoint, client.get("id"), api_key_value, "QUOTA_EXCEEDED", started_ts, {"per_day": per_day, "limit": qpd})
            return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=qpd, window_seconds=86400, used=per_day)

        return {"client": client, "usage": {"per_minute_used": per_min, "per_day_used": per_day, "quota_per_minute": qpm, "quota_per_day": qpd}}, None

    started = time.time()

    if api_key is None or not isinstance(api_key, str):
        _log("list_search_queries", None, None, "VALIDATION_ERROR", started, {"reason": "api_key_type"})
        return _err("VALIDATION_ERROR", "api_key must be a string.")

    if status is not None:
        if not isinstance(status, str):
            _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "status_type"})
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in {"queued", "running", "succeeded", "failed"}:
            _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "status_enum"})
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["queued", "running", "succeeded", "failed"])

    if search_type is not None:
        if not isinstance(search_type, str):
            _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "search_type_type"})
            return _err("VALIDATION_ERROR", "search_type must be a string.")
        if search_type not in {"general", "user", "video", "live", "article"}:
            _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "search_type_enum"})
            return _err("VALIDATION_ERROR", "Invalid search_type.", allowed=["general", "user", "video", "live", "article"])

    if keyword is not None and not isinstance(keyword, str):
        _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "keyword_type"})
        return _err("VALIDATION_ERROR", "keyword must be a string.")

    if limit is None:
        limit = 20
    if not isinstance(limit, int):
        _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "limit_type"})
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 100:
        _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "limit_range"})
        return _err("VALIDATION_ERROR", "limit out of range (1..100).")

    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "cursor_type"})
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            # Expect "created_at|id"
            parts = raw.split("|", 1)
            if len(parts) != 2:
                raise ValueError("bad cursor")
            start_after = {"created_at": parts[0], "id": parts[1]}
        except Exception:
            _log("list_search_queries", None, api_key, "VALIDATION_ERROR", started, {"reason": "cursor_decode"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    ctx, e = _auth_and_limits("list_search_queries", api_key, started)
    if e:
        return e
    client = ctx["client"]

    rows = _load("search_queries.json")
    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client.get("id"):
            continue
        if status is not None and r.get("status") != status:
            continue
        if search_type is not None and r.get("search_type") != search_type:
            continue
        if keyword is not None:
            k = r.get("keyword")
            if not isinstance(k, str) or keyword.lower() not in k.lower():
                continue
        filtered.append(r)

    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.min
        return (dt, str(r.get("id") or ""))

    filtered.sort(key=_sort_key, reverse=True)

    if start_after:
        after_dt = _parse_dt(start_after["created_at"])
        after_id = start_after["id"]
        if after_dt is None:
            _log("list_search_queries", client.get("id"), api_key, "VALIDATION_ERROR", started, {"reason": "cursor_dt_parse"})
            return _err("VALIDATION_ERROR", "Invalid cursor timestamp.")
        trimmed = []
        for r in filtered:
            r_dt = _parse_dt(r.get("created_at")) or datetime.datetime.min
            r_id = str(r.get("id") or "")
            # sorted desc; include those strictly older than cursor tuple
            if r_dt < after_dt or (r_dt == after_dt and r_id < after_id):
                trimmed.append(r)
        filtered = trimmed

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        payload = f"{last.get('created_at','')}|{last.get('id','')}"
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8")

    # Update last_used_at on successful request
    try:
        api_clients = _load("api_clients.json")
        now_iso = _now_iso()
        for r in api_clients:
            if isinstance(r, dict) and r.get("id") == client.get("id"):
                r["last_used_at"] = now_iso
                r["updated_at"] = now_iso
                _save("api_clients.json", api_clients)
                break
    except Exception:
        pass

    _log("list_search_queries", client.get("id"), api_key, "OK", started, {"returned": len(page), "total": len(filtered)})

    # Return metadata-only rows (as described), but include common fields
    items = []
    for r in page:
        items.append({
            "id": r.get("id"),
            "tool_name": r.get("tool_name"),
            "keyword": r.get("keyword"),
            "search_type": r.get("search_type"),
            "page": r.get("page"),
            "status": r.get("status"),
            "cache_hit": r.get("cache_hit"),
            "expires_at": r.get("expires_at"),
            "started_at": r.get("started_at"),
            "finished_at": r.get("finished_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
            "error_code": r.get("error_code"),
            "error_message": r.get("error_message"),
        })

    return {
        "items": items,
        "meta": {
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor if has_more else None,
            "total": len(filtered),
        },
        "rate_limit": ctx["usage"],
    }

def get_search_query(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0168000" if __import__("os").path.isdir("./environment_mix/0168000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, client_id, credential, status_code, started, error_code=None):
        fn = _ensure_request_logs()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        finished = time.time()
        logs.append(
            {
                "id": f"req_{int(finished*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "client_id": client_id,
                "credential": credential,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int(max(0, (finished - started) * 1000)),
                "created_at": _now_iso(),
            }
        )
        _save(fn, logs)

    def _auth_client_by_api_key(api_key_value):
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        token = api_key_value.strip()
        # Authenticate by matching the stored client-visible value (api_key_hash field is used as the token in this datastore)
        for c in clients:
            if isinstance(c, dict) and (c.get("api_key_hash") == token or c.get("id") == token or c.get("name") == token):
                return c
        return None

    def _enforce_rate_limits(client_id, per_minute, per_day):
        # Uses request_logs.json as the observable counter source
        logs = _load(_ensure_request_logs())
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        c_min = 0
        c_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_iso(r.get("created_at"))
            if not ts:
                continue
            if ts >= day_ago:
                c_day += 1
            if ts >= minute_ago:
                c_min += 1

        # Next request would be +1
        if isinstance(per_minute, int) and per_minute > 0 and (c_min + 1) > per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded: quota_per_minute reached.", quota_per_minute=per_minute)
        if isinstance(per_day, int) and per_day > 0 and (c_day + 1) > per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded: quota_per_day reached.", quota_per_day=per_day)
        return None

    started = time.time()
    endpoint = "get_search_query"
    client = None
    client_id = None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log(endpoint, None, None, 401, started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if not isinstance(id, str) or not id.strip():
        # log under unauthenticated? we do have api_key but might be invalid; still try auth for attribution rule
        client = _auth_client_by_api_key(api_key)
        client_id = client.get("id") if isinstance(client, dict) else None
        _log(endpoint, client_id, api_key.strip(), 400, started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid id: must be a non-empty string.", id=id)

    # Authenticate
    client = _auth_client_by_api_key(api_key)
    if not client:
        _log(endpoint, None, api_key.strip(), 401, started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid api_key.")
    client_id = client.get("id")

    # Enforce client active status
    if client.get("status") != "active":
        _log(endpoint, client_id, api_key.strip(), 403, started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client is not active; request rejected by business rule.", client_status=client.get("status"))

    # Enforce rate/quota before performing operation (and must not create other rows)
    rl_err = _enforce_rate_limits(client_id, client.get("quota_per_minute"), client.get("quota_per_day"))
    if rl_err:
        code = rl_err["error"]["code"]
        _log(endpoint, client_id, api_key.strip(), 429, started, error_code=code)
        return rl_err

    # Fetch query by id; this endpoint returns NOT_FOUND if not owned by caller
    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        queries = []

    row = None
    for q in queries:
        if isinstance(q, dict) and q.get("id") == id and q.get("client_id") == client_id:
            row = q
            break

    if not row:
        _log(endpoint, client_id, api_key.strip(), 404, started, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Search query not found for this client.", id=id)

    # Successful read: update client's last_used_at/updated_at
    now_iso = _now_iso()
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _save("api_clients.json", clients)

    _log(endpoint, client_id, api_key.strip(), 200, started)

    return {
        "data": row,
        "meta": {
            "client_id": client_id,
        },
    }

