    if not q:
        _log("list_search_results", client.get("id"), api_key, "NOT_FOUND", started, {"query_id": query_id})
        return _err("NOT_FOUND", "Search query not found.")

    results = _load("search_results.json")
    filtered = []
    for r in results:
        if not isinstance(r, dict):
            continue
        if r.get("query_id") != query_id:
            continue
        if result_type is not None and r.get("result_type") != result_type:
            continue
        if exact_match is not None and r.get("exact_match") is not exact_match:
            continue
        filtered.append(r)

    # Order by rank ascending
    def _rank_key(r):
        rk = r.get("rank")
        try:
            return int(rk)
        except Exception:
            return 10**9

    filtered.sort(key=_rank_key)

    total = len(filtered)
    page = filtered[offset:offset + limit]

    # Update last_used_at on successful request
    try:
        api_clients = _load("api_clients.json")
        now_iso = _now_iso()
        for r in api_clients:
            if isinstance(r, dict) and r.get("id") == client.get("id"):
                r["last_used_at"] = now_iso
                r["updated_at"] = now_iso
                _save("api_clients.json", api_clients)
                break
    except Exception:
        pass

    _log("list_search_results", client.get("id"), api_key, "OK", started, {"query_id": query_id, "returned": len(page), "total": total})

    items = []
    for r in page:
        items.append({
            "id": r.get("id"),
            "query_id": r.get("query_id"),
            "result_type": r.get("result_type"),
            "rank": r.get("rank"),
            "title": r.get("title"),
            "exact_match": r.get("exact_match"),
            "external_id": r.get("external_id"),
            "bv_id": r.get("bv_id"),
            "author_name": r.get("author_name"),
            "url": r.get("url"),
            "raw_payload": r.get("raw_payload"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    return {
        "items": items,
        "meta": {
            "query_id": query_id,
            "offset": offset,
            "limit": limit,
            "total": total,
            "has_more": (offset + len(page)) < total,
            "next_offset": (offset + len(page)) if (offset + len(page)) < total else None,
        },
        "rate_limit": ctx["usage"],
    }

def list_danmaku_requests(api_key, status=None, bv_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0168000" if __import__("os").path.isdir("./environment_mix/0168000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # --- helpers ---
    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log_request(client_id, endpoint, credential, status_code, error_code=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "client_id": client_id,
            "endpoint": endpoint,
            "credential": credential,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso,
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _same_utc_date(a, b):
        return a.date() == b.date()

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    # --- validate inputs ---
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if status is not None:
        if not isinstance(status, str) or status not in ["queued", "running", "succeeded", "failed"]:
            return _err("VALIDATION_ERROR", "status must be one of queued|running|succeeded|failed")
    if bv_id is not None:
        if not isinstance(bv_id, str) or re.match(r"^BV[0-9A-Za-z]{10}$", bv_id) is None:
            return _err("VALIDATION_ERROR", "bv_id must match pattern ^BV[0-9A-Za-z]{10}$")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # --- authenticate ---
    clients = _load("api_clients.json")
    client = None
    # NOTE: api_key_hash is a stored value; per contract, authenticate by direct match to client-visible value or id.
    for c in clients:
        if c.get("api_key_hash") == api_key or c.get("id") == api_key:
            client = c
            break
    if client is None:
        _log_request(None, "list_danmaku_requests", api_key, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key")

    if client.get("status") != "active":
        _log_request(client.get("id"), "list_danmaku_requests", api_key, 403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client is not active")

    # --- rate limit / quota ---
    logs = _load("request_logs.json")
    minute_start = _minute_bucket(now)
    day_start = datetime.datetime(now.year, now.month, now.day)
    per_min = 0
    per_day = 0
    for r in logs:
        if r.get("client_id") != client.get("id"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if _minute_bucket(dt) == minute_start:
            per_min += 1
        if dt >= day_start and _same_utc_date(dt, now):
            per_day += 1

    qpm = client.get("quota_per_minute")
    qpd = client.get("quota_per_day")
    if not isinstance(qpm, int) or not isinstance(qpd, int):
        _log_request(client.get("id"), "list_danmaku_requests", api_key, 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Client quota configuration is invalid")

    if per_min >= qpm:
        _log_request(client.get("id"), "list_danmaku_requests", api_key, 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests (per-minute quota exceeded)")
    if per_day >= qpd:
        _log_request(client.get("id"), "list_danmaku_requests", api_key, 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # --- decode cursor ---
    start_after_created_at = None
    start_after_id = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"=" * (-len(cursor) % 4)).decode("utf-8")
            payload = json.loads(raw)
            if isinstance(payload, dict):
                start_after_created_at = payload.get("created_at")
                start_after_id = payload.get("id")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # --- query data ---
    reqs = _load("danmaku_requests.json")
    rows = [r for r in reqs if r.get("client_id") == client.get("id")]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if bv_id is not None:
        rows = [r for r in rows if r.get("bv_id") == bv_id]

    # Sort by created_at desc, then id desc for stable pagination
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor: return items strictly "after" the cursor in this ordering
    if start_after_created_at and start_after_id:
        cut_dt = _parse_dt(start_after_created_at) or datetime.datetime(1970, 1, 1)
        cut_id = str(start_after_id)
        filtered = []
        for r in rows:
            rdt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
            rid = str(r.get("id") or "")
            # since sorted desc, we skip until we pass the cursor element
            if (rdt, rid) < (cut_dt, cut_id):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page_rows = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page_rows:
        last = page_rows[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        enc = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8")
        next_cursor = enc.rstrip("=")

    # Update client last_used_at for successful request
    client["last_used_at"] = now_iso
    client["updated_at"] = now_iso
    for i, c in enumerate(clients):
        if c.get("id") == client.get("id"):
            clients[i] = client
            break
    try:
        _save("api_clients.json", clients)
    except Exception:
        _log_request(client.get("id"), "list_danmaku_requests", api_key, 500, "CONFLICT")
        return _err("CONFLICT", "Failed to persist client usage metadata")

    _log_request(client.get("id"), "list_danmaku_requests", api_key, 200, None)
    return {
        "data": page_rows,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def update_danmaku_response_status(api_key, id, status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0168000" if __import__("os").path.isdir("./environment_mix/0168000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, client_id, credential, status_code, started, error_code=None):
        fn = _ensure_request_logs()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        finished = time.time()
        logs.append(
            {
                "id": f"req_{int(finished*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "client_id": client_id,
                "credential": credential,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int(max(0, (finished - started) * 1000)),
                "created_at": _now_iso(),
            }
        )
        _save(fn, logs)

    def _auth_client_by_api_key(api_key_value):
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        token = api_key_value.strip()
        # Authenticate by matching the stored client-visible value (api_key_hash field is used as the token in this datastore)
        for c in clients:
            if isinstance(c, dict) and (c.get("api_key_hash") == token or c.get("id") == token or c.get("name") == token):
                return c
        return None

    def _enforce_rate_limits(client_id, per_minute, per_day):
        logs = _load(_ensure_request_logs())
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        c_min = 0
        c_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_iso(r.get("created_at"))
            if not ts:
                continue
            if ts >= day_ago:
                c_day += 1
            if ts >= minute_ago:
                c_min += 1

        if isinstance(per_minute, int) and per_minute > 0 and (c_min + 1) > per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded: quota_per_minute reached.", quota_per_minute=per_minute)
        if isinstance(per_day, int) and per_day > 0 and (c_day + 1) > per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded: quota_per_day reached.", quota_per_day=per_day)
        return None

    started = time.time()
    endpoint = "update_danmaku_response_status"
    client = None
    client_id = None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log(endpoint, None, None, 401, started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if not isinstance(id, str) or not id.strip():
        client = _auth_client_by_api_key(api_key)
        client_id = client.get("id") if isinstance(client, dict) else None
        _log(endpoint, client_id, api_key.strip(), 400, started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid id: must be a non-empty string.", id=id)
    if status not in ("fresh", "stale", "purged"):
        client = _auth_client_by_api_key(api_key)
        client_id = client.get("id") if isinstance(client, dict) else None
        _log(endpoint, client_id, api_key.strip(), 400, started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status: must be one of 'fresh', 'stale', 'purged'.", status=status)

    # Authenticate
    client = _auth_client_by_api_key(api_key)
    if not client:
        _log(endpoint, None, api_key.strip(), 401, started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid api_key.")
    client_id = client.get("id")

    # Enforce active status
    if client.get("status") != "active":
        _log(endpoint, client_id, api_key.strip(), 403, started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client is not active; request rejected by business rule.", client_status=client.get("status"))

    # Enforce rate/quota before performing mutation
    rl_err = _enforce_rate_limits(client_id, client.get("quota_per_minute"), client.get("quota_per_day"))
    if rl_err:
        code = rl_err["error"]["code"]
        _log(endpoint, client_id, api_key.strip(), 429, started, error_code=code)
        return rl_err

    # Load response row
    responses = _load("danmaku_responses.json")
    if not isinstance(responses, list):
        responses = []

    target = None
    for r in responses:
        if isinstance(r, dict) and r.get("id") == id:
            target = r
            break

    if not target:
        _log(endpoint, client_id, api_key.strip(), 404, started, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Danmaku response not found.", id=id)

    current = target.get("status")
    transitions = {
        "fresh": {"stale", "purged"},
        "stale": {"fresh", "purged"},
        "purged": set(),
    }

    if current not in transitions:
        # Data corruption / unknown state
        _log(endpoint, client_id, api_key.strip(), 409, started, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Current danmaku response status is invalid; cannot transition.", current_status=current)

    # Idempotent update: if already in desired status, return row (still counts as a request; mutation has no effect but is idempotent)
    if current == status:
        # Update client's last_used_at/updated_at for a successful call
        now_iso = _now_iso()
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                c["last_used_at"] = now_iso
                c["updated_at"] = now_iso
                break
        _save("api_clients.json", clients)

        _log(endpoint, client_id, api_key.strip(), 200, started)
        return {"data": target, "meta": {"idempotent": True}}

    if status not in transitions[current]:
        _log(endpoint, client_id, api_key.strip(), 409, started, error_code="INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "Invalid danmaku response status transition per lifecycle rules.",
            from_status=current,
            to_status=status,
            allowed=sorted(list(transitions[current])),
        )

    # Apply transition
    now_iso = _now_iso()
    target["status"] = status
    target["updated_at"] = now_iso

    _save("danmaku_responses.json", responses)

    # Successful call bookkeeping
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _save("api_clients.json", clients)

    _log(endpoint, client_id, api_key.strip(), 200, started)

    return {"data": target, "meta": {"updated": True}}
